import{_ as i}from"./chunks/Audio.COine8Wh.js";import{c as s,o as a,j as t,G as r,ae as n,a as o}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS","description":"","frontmatter":{"legisId":"2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors","title":"DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/08/democratizing-access-to-alternative-assets-for-401k-investors/","publishDate":"2025-08-07T17:01:02-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors\\",\\"datePublished\\":\\"2025-08-07T17:01:02-04:00\\",\\"dateModified\\":1771637292000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors.md","filePath":"executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors.md","lastUpdated":1771637292000}'),l={name:"executive-orders/2025-08-07-democratizing-access-to-alternative-assets-for-401k-investors.md"},v=Object.assign(l,{setup(c){return(d,e)=>(a(),s("div",null,[e[0]||(e[0]=t("h1",{id:"democratizing-access-to-alternative-assets-for-401-k-investors",tabindex:"-1"},[o("DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS "),t("a",{class:"header-anchor",href:"#democratizing-access-to-alternative-assets-for-401-k-investors","aria-label":'Permalink to "DEMOCRATIZING ACCESS TO ALTERNATIVE ASSETS FOR 401(K) INVESTORS"'},"​")],-1)),r(i),e[1]||(e[1]=n('<p>Published on Thursday, August 7, 2025</p><ul><li><p><strong>Background</strong></p><ul><li>Wealthy Americans and government workers have access to alternative assets, but most of the 90 million participants in defined-contribution plans do not.</li><li>Fiduciaries must carefully evaluate all aspects of alternative asset investments to safeguard retirement accounts.</li></ul></li><li><p><strong>Previous Action</strong></p><ul><li>The 2020 information letter from the Administration aimed to promote alternative asset investments in retirement plans.</li></ul></li><li><p><strong>Current Challenges</strong></p><ul><li>Burdensome lawsuits and prior Department of Labor guidance have limited access to alternative assets, reducing investment opportunities and returns for many Americans.</li><li>Regulatory overreach has hindered investment innovation for 401(k) and defined-contribution plan participants.</li></ul></li><li><p><strong>New Policy</strong></p><ul><li>Every American preparing for retirement should have access to investments in alternative assets, as determined appropriate by the plan fiduciary.</li></ul></li><li><p><strong>Definition of Alternative Assets</strong></p><ul><li>Includes: <ul><li>Private market investments not traded on public exchanges.</li><li>Real estate interests and debt instruments secured by real estate.</li><li>Actively managed investment vehicles in digital assets.</li><li>Commodities investment.</li><li>Investments in infrastructure development projects.</li><li>Lifetime income strategies including longevity risk-sharing pools.</li></ul></li></ul></li><li><p><strong>Mandates for the Secretary of Labor</strong></p><ul><li>Within 180 days: <ul><li>Reexamine fiduciary duties under ERISA concerning alternative asset investments.</li><li>Clarify the Department of Labor’s position on these assets and fiduciary processes.</li><li>Propose rules or guidance that help fiduciaries balance expenses with investment objectives and may include safe harbors.</li><li>Consult with the Secretary of the Treasury and the SEC to support policy objectives.</li></ul></li></ul></li><li><p><strong>SEC Responsibilities</strong></p><ul><li>Consider ways to enhance access to alternative asset investments for defined-contribution retirement plans.</li></ul></li><li><p><strong>Legal and Applicability Statements</strong></p><ul><li>The order doesn’t affect existing legal authorities or create enforceable rights against the United States.</li><li>Implementation will align with applicable laws and available appropriations.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/08/democratizing-access-to-alternative-assets-for-401k-investors/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/08/democratizing-access-to-alternative-assets-for-401k-investors/</a></p>',3))]))}});export{m as __pageData,v as default};
